import{z as i,x as B,o as s,c as p,q as d,j as E,D as e,d as o,s as l,S as n,b as t}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"tty 与 PTY","description":"","frontmatter":{"title":"tty 与 PTY","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tty-pty.md","filePath":"cs/tty-pty.md","lastUpdated":1791413859000}'),c={name:"cs/tty-pty.md"};function A(m,a,h,T,y,f){const r=B("Mermaid");return s(),p("div",null,[a[2]||(a[2]=d('<h1 id="tty-与-pty" tabindex="-1">tty 与 PTY <a class="header-anchor" href="#tty-与-pty" aria-label="Permalink to &quot;tty 与 PTY&quot;">​</a></h1><div class="epigraph"><p>终端是带行规程的字符设备：规范模式处理擦除与行编辑；伪终端把同一套接口接到一对主从描述符。</p><footer>—— 据 Ritchie and Thompson；Stevens and Rago, APUE；Linux tty 文档整理</footer></div><p><a href="/cs/hrtimer">上一课</a>能做超时，shell 交互还缺「键盘与屏幕」这份文件。<a href="/cs/signals">信号</a> 的 <code>SIGINT</code> 来自终端驱动。<a href="/cs/process-image">进程组</a> 与会话（树里若已有）把前台作业接到控制终端。缺口是 <strong>tty 行规程与 PTY</strong>：不是硬件 UART 百科，而是内核对象如何把字节变成行、以及 sshd 如何用伪终端。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若把串口当原始字节管道，退格、Ctrl-C、作业控制都要每个程序自己做。Unix：行规程插在驱动与 <code>read</code> 之间——规范模式攒一行再给进程，INTR 字符变成信号。PTY：没有真实串口，master 端像「对端键盘」，slave 端对进程就是 tty。缺口是这对对象，加上 <code>TIOCSWINSZ</code> 窗口大小。</p><p>本课不把 termios 的每一位 flag 背完。</p><p><span class="marginnote">会话的控制终端接收挂断信号。后台写终端可被 <code>SIGTTOU</code> 停。本课讲机制，不写如何抢 tty 做对抗。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>真实 tty：UART 中断 → 行规程 → 等待 <code>read</code> 的进程。PTY：用户写 master → 行规程 → slave 的 <code>read</code>；进程写 slave → master 的 <code>read</code>（给仿真器画屏）。<code>open(&quot;/dev/ptmx&quot;)</code> 取得一对。窗口改变投递 <code>SIGWINCH</code>。与 <a href="/cs/vfs">VFS</a> 接头：都是字符设备 inode。</p>',9)),(s(),E(n,null,{default:e(()=>[l(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20KEY%5B%22%E9%94%AE%E7%9B%98%E6%88%96%20PTY%20master%22%5D%20--%3E%20LD%5B%22%E8%A1%8C%E8%A7%84%E7%A8%8B%22%5D%0A%20%20LD%20--%3E%20SLAVE%5B%22%E8%BF%9B%E7%A8%8B%20read%20%E4%BB%8E%20tty%22%5D%0A%20%20SLAVE%20--%3E%20OUT%5B%22%E5%86%99%E5%9B%9E%E5%B1%8F%E5%B9%95%E6%88%96%20master%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[o("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"tty 把「用户」接到进程组：中断字符是信号源，行编辑是内核里的小状态机。PTY 让网络与图形仿真器复用同一抽象，而不在内核里放 SSH 协议。不要把这写成 X11 或 Wayland 课。缓冲仍可能阻塞，select/epoll 对 tty fd 有效。",-1)),a[5]||(a[5]=t("p",null,"规范模式下，一次键入序列在行规程内部发生了什么：",-1)),(s(),E(n,null,{default:e(()=>[l(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20K%5B%22%E9%94%AE%E5%85%A5%20a%20b%20c%20%E9%80%80%E6%A0%BC%20d%20%E5%9B%9E%E8%BD%A6%22%5D%20--%3E%20L%5B%22%E8%A1%8C%E8%A7%84%E7%A8%8B%E5%86%85%E6%A0%B8%E7%BC%93%E5%86%B2%E5%8C%BA%22%5D%0A%20%20L%20--%3E%20BS%5B%22%E9%80%80%E6%A0%BC%3A%20%E6%8A%B9%E6%8E%89%E7%BC%93%E5%86%B2%E5%86%85%E4%B8%8A%E4%B8%80%E5%AD%97%E7%AC%A6%22%5D%0A%20%20L%20--%3E%20NL%5B%22%E5%9B%9E%E8%BD%A6%3A%20%E8%A1%8C%E5%B7%B2%E5%AE%8C%E6%95%B4%22%5D%0A%20%20BS%20--%3E%20BUF%5B%22%E7%BC%93%E5%86%B2%E7%8E%B0%E4%B8%BA%20abd%22%5D%0A%20%20NL%20--%3E%20DELIVER%5B%22read%20%E4%B8%80%E6%AC%A1%E8%BF%94%E5%9B%9E%E6%95%B4%E8%A1%8C%20abd%22%5D%0A%20%20INTR%5B%22Ctrl-C%20%E4%B8%8D%E8%BF%9B%E7%BC%93%E5%86%B2%22%5D%20--%3E%20SIG%5B%22%E7%9B%B4%E6%8E%A5%E5%90%91%E5%89%8D%E5%8F%B0%E8%BF%9B%E7%A8%8B%E7%BB%84%E5%8F%91%20SIGINT%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=d('<p><span class="marginnote">常见误区：退格<strong>不是程序</strong>处理的。规范模式下内核行规程在你按回车之前就完成了编辑，进程 <code>read</code> 拿到的已经是删干净的 <code>abd</code>。只有切到原始模式（vim、<code>ssh</code> 这类全屏或透传程序），才由程序自己收原始字节、自己管编辑。</span></p><p><span class="marginnote">直觉类比：PTY 的 master–slave 像一对对讲机——sshd 对着 master 说话，slave 那头的进程以为自己在听一台真键盘；进程的输出也从 slave 吐回 master，由 ssh 画进你本地窗口。内核里从头到尾没有一根串口线。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 systemd 的 getty 单元全文——init 课会接。不保证所有嵌入式没有 tty。下一课：这类驱动常常做成可加载模块，而不编进 vmlinux。</p><p><span class="marginnote">术语翻译：行规程（line discipline）就是内核里的一小块「打字机前台」——替<strong>所有</strong>程序统一处理擦除、回显、Ctrl-C 转信号，让每个程序都不必重写这套交互细节；<code>stty raw</code> 做的事只是把它撤下来。</span></p><p>后课默认：交互式程序有 tty 语义。内核代码如何在运行时接上，下一课内核模块。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>行规程实现规范输入与终端信号。</li><li>PTY 用主从描述符仿真同一接口。</li><li>可加载驱动是模块课的缺口。</li><li>出处：Ritchie and Thompson；Stevens and Rago, <em>APUE</em>；Linux tty。</li></ul>',8))])}const D=i(c,[["render",A]]);export{C as __pageData,D as default};
